from fastapi import APIRouter, FastAPI, Security
from fastapi.responses import JSONResponse
from fastapi.security import APIKeyHeader

key = APIKeyHeader(name='X-Key')
callbacks = APIRouter(default_response_class=JSONResponse)

@callbacks.post('/callback')
def callback(token=Security(key)):
    return {}

app = FastAPI()

@app.post('/start', callbacks=callbacks.routes)
def start():
    return {}

schema = app.openapi()
assert 'APIKeyHeader' in schema['components']['securitySchemes']

from fastapi import FastAPI, Security
from fastapi.security import HTTPDigest
from fastapi.testclient import TestClient

app = FastAPI()
security = HTTPDigest(auto_error=False)

@app.get('/')
def endpoint(credential=Security(security)):
    return {'credential': credential}

response = TestClient(app).get('/', headers={'Authorization': 'Bearer token'})
assert response.status_code == 200
